static void set(Phobos67Processor& p,const char* id,float value){auto* v=p.state.getParameter(id);v->setValueNotifyingHost(v->convertTo0to1(value));}
struct DspProbeAccess {static bool sameFilterDesign(const Phobos67Processor& a,const Phobos67Processor& b){return a.air[0].c==b.air[0].c&&a.sub[0].c==b.sub[0].c&&a.sub[0].robust==b.sub[0].robust&&(!a.sub[0].robust||a.sub[0].dc==b.sub[0].dc)&&a.airTransition==0&&a.subTransition==0;}static void immediateFilters(Phobos67Processor& p){p.airTransition=p.subTransition=0;p.oldFilter[0]=-1;}static float inflate(Phobos67Processor& p,float x,float c,float e,bool clip,int ch,bool split){return p.processInflator(x,c,e,clip,ch,split);}};
