int main(int argc,char** argv){juce::ScopedJuceInitialiser_GUI init;Phobos67Processor p;
for(int a=4;a<argc;a++){auto s=juce::String(argv[a]);auto id=s.upToFirstOccurrenceOf("=",false,false);if(auto* v=p.state.getParameter(id))v->setValueNotifyingHost(v->convertTo0to1(s.fromFirstOccurrenceOf("=",false,false).getFloatValue()));}
if(argc>1&&juce::String(argv[1])=="--module-meters")return ScopeProbeAccess::moduleCheck()?0:32;
if(argc>1&&juce::String(argv[1])=="--autolevel"){
 try{for(double rate:{44100.,48000.,96000.,192000.})for(int block:{17,128,1024}){Phobos67Processor q;set(q,"output",-12);set(q,"clip",0);q.prepareToPlay(rate,block);juce::AudioBuffer<float>b(2,block);juce::MidiBuffer m;int position=0;for(int k=0;k<(int)(rate*.2/block)+1;k++){functional::signal(b,position,.1f,rate);position+=block;q.processBlock(b,m);}set(q,"volumeComp",1);float previous=0;unsigned long allocations=0;for(int k=0;k<(int)(rate*8/block)+1;k++){functional::signal(b,position,.1f,rate);position+=block;beginAllocationMonitoring();q.processBlock(b,m);allocations+=endAllocationMonitoring();float db=q.volumeMatchDb.load();functional::require(db-previous<=2*block/rate+.001,"Makeup gain rose too fast");if(k*block<rate*.49)functional::require(std::abs(db)<.01,"Makeup before warmup");previous=db;}functional::require(previous>11.5f&&previous<=12.01f,"Compensation failed to settle");for(int k=0;k<(int)(rate/block)+1;k++){functional::signal(b,position,1e-6f,rate);position+=block;q.processBlock(b,m);}functional::require(std::abs(q.volumeMatchDb.load())<.01,"Noise retained makeup gain");for(int k=0;k<(int)(rate*.4/block)+1;k++){functional::signal(b,position,.1f,rate);position+=block;q.processBlock(b,m);}functional::require(std::abs(q.volumeMatchDb.load())<.01,"Restart skipped warmup");functional::require(allocations==0,"Autolevel allocated in callback");}
 std::cout<<"PASS COMP VOL activation warmup, makeup <=2 dB/s, convergence, noise returns to unity, restart warmup and zero allocations: 4 rates x 3 block sizes\n";return 0;}catch(const std::exception& ex){endAllocationMonitoring();std::cout<<"FAIL "<<ex.what()<<"\n";return 40;}}
if(argc>1&&juce::String(argv[1])=="--wheel")return ScopeProbeAccess::wheelCheck()?0:31;
if(argc>1&&juce::String(argv[1])=="--ui")return ScopeProbeAccess::check()?0:30;
if(argc>1&&juce::String(argv[1])=="--functional")return functional::run();
if(argc>1&&juce::String(argv[1])=="--benchmark"){
 p.prepareToPlay(48000,256);juce::AudioBuffer<float> b(2,256);juce::MidiBuffer m;set(p,"even",35);set(p,"effect",60);
 double elapsed=0;for(int k=0;k<6000;k++){for(int j=0;j<256;j++){b.setSample(0,j,.3f*std::sin((k*256+j)*.13));b.setSample(1,j,.2f*std::sin((k*256+j)*.17));}double t=juce::Time::getMillisecondCounterHiRes();p.processBlock(b,m);elapsed+=juce::Time::getMillisecondCounterHiRes()-t;}
 std::cout<<"Audio processBlock ms: "<<elapsed<<"; audio duration ms: 32000; realtime CPU percent of one core: "<<elapsed/320<<"\n";return 0;}
if(argc>3&&juce::String(argv[1])=="--render"){p.prepareToPlay(std::getenv("PHOBOS_PROBE_RATE")?std::atof(std::getenv("PHOBOS_PROBE_RATE")):48000,256);std::ifstream in(argv[2],std::ios::binary),right(std::string(argv[2])+".right",std::ios::binary);std::ofstream out(argv[3],std::ios::binary),rightOut(std::string(argv[3])+".right",std::ios::binary);juce::AudioBuffer<float> b(2,256);juce::MidiBuffer m;while(in.read((char*)b.getWritePointer(0),1024)||in.gcount()){int n=(int)in.gcount()/4;for(int i=n;i<256;i++)b.setSample(0,i,0);b.copyFrom(1,0,b,0,0,256);if(right.is_open())right.read((char*)b.getWritePointer(1),1024);p.processBlock(b,m);rightOut.write((char*)b.getReadPointer(1),n*4);out.write((char*)b.getReadPointer(0),n*4);}return 0;}

if(argc>2&&juce::String(argv[1])=="--preview"){
 p.setRateAndBufferSizeDetails(48000,256);p.prepareToPlay(48000,256);Phobos67Editor editor(p);int width=argc>3?juce::String(argv[3]).getIntValue():900;editor.setSize(width,juce::roundToInt(width*.6));set(p,"even",35);set(p,"effect",60);juce::AudioBuffer<float> buffer(2,256);juce::MidiBuffer midi;
 for(int block=0;block<48;block++){for(int j=0;j<256;j++){float v=.6f*std::sin(juce::MathConstants<double>::twoPi*997*(block*256+j)/48000);buffer.setSample(0,j,v);buffer.setSample(1,j,v*.8f);}p.processBlock(buffer,midi);if(block%8==7)ScopeProbeAccess::tick(editor);}
 ScopeProbeAccess::setup(editor,argc>4?juce::String(argv[4]).getIntValue():1,argc>5&&juce::String(argv[5])=="black",argc>5&&juce::String(argv[5])=="ads",argc>5&&juce::String(argv[5])=="fl",argc>5?juce::String(argv[5]).getIntValue():14);auto image=editor.createComponentSnapshot(editor.getLocalBounds());juce::FileOutputStream output{juce::File(juce::String(argv[2]))};output.setPosition(0);output.truncate();return juce::PNGImageFormat().writeImageToStream(image,output)?0:1;
}
return functional::run();}



